// Crossbeam MCP find_overlapping_accounts_and_leads, one input item per page:
// json.structuredContent.result = { status, data: [rows], pagination, list_link } (same object in content[0].text).
// Each row: record_id, record_name, website, overlap_time, partner_names[], partner_segments[].
const cfg = $('Configure me').first().json;
const ignore = String(cfg.partners_to_ignore || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
function getResult(j) {
  if (j.structuredContent && j.structuredContent.result) return j.structuredContent.result;
  let t = Array.isArray(j.content) && j.content[0] ? j.content[0].text : null;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
  return (t && t.result) ? t.result : (t || {});
}
const byId = {};
let link = '';
let incomplete = false;
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error) { incomplete = true; continue; }
  const res = getResult(j);
  if (String(res.status || '').toLowerCase() === 'retry') incomplete = true;
  if (!link && res.list_link) link = String(res.list_link);
  for (const r of (Array.isArray(res.data) ? res.data : [])) {
    if (!r || !r.record_id) continue;
    const names = [...new Set((r.partner_names || []).map(n => String(n).trim())
      .filter(n => n && !ignore.some(b => n.toLowerCase().includes(b))))].sort();
    if (!names.length) continue;
    byId[r.record_id] = {
      record_id: String(r.record_id),
      record_name: String(r.record_name || ''),
      website: String(r.website || ''),
      overlap_time: String(r.overlap_time || ''),
      partner_list: names.join('|'),
      partner_count: names.length,
      // partner_segments says whether any partner has this account as an open opportunity
      has_partner_opp: (r.partner_segments || []).includes('open_opportunities')
    };
  }
}
return Object.values(byId).map(a => ({ json: Object.assign(a, { list_link: link, fetch_incomplete: incomplete }) }));

// Crossbeam MCP find_new_accounts, one input item per page: json.structuredContent.result.data = [{ name, domain,
// industry, country, employee_range, last_partner_customer_date, customer_of_partners: [{ partner_name, is_recommended }] }].
// Coverage score = number of partners + 2 x partners Crossbeam flags as recommended.
const cfg = $('Configure me').first().json;
const ignore = String(cfg.partners_to_ignore || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
function rowsOf(j) {
  const sc = j.structuredContent;
  if (sc && sc.result && Array.isArray(sc.result.data)) return sc.result.data;
  let t = Array.isArray(j.content) && j.content[0] ? j.content[0].text : null;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
  if (t && t.result && Array.isArray(t.result.data)) return t.result.data;
  return (t && Array.isArray(t.data)) ? t.data : [];
}
const out = [];
for (const it of $input.all()) {
  for (const r of rowsOf(it.json || {})) {
    const domain = String((r && r.domain) || '').trim().toLowerCase();
    if (!domain) continue;
    const names = [];
    let recommended = 0;
    for (const p of (r.customer_of_partners || [])) {
      const n = String((p && p.partner_name) || '').trim();
      if (!n || ignore.some(b => n.toLowerCase().includes(b))) continue;
      if (!names.includes(n)) names.push(n);
      if (p.is_recommended === true) recommended += 1;
    }
    out.push({ json: {
      domain: domain,
      account_name: String(r.name || domain),
      industry: String(r.industry || ''),
      country: String(r.country || ''),
      employee_range: String(r.employee_range || ''),
      last_partner_customer_date: String(r.last_partner_customer_date || ''),
      partner_list: names.sort().join(', '),
      partner_count: names.length,
      recommended_partner_count: recommended,
      coverage_score: names.length + 2 * recommended
    } });
  }
}
// One empty placeholder keeps the branch alive when Crossbeam returns nothing (dropped by the filters below).
return out.length ? out : [{ json: { domain: '', partner_count: 0, coverage_score: 0 } }];

// Crossbeam MCP get_partner_suggestions returns json.structuredContent.data = [{ name, domain, invite_url }]
// (same object in content[0].text). It returns no overlap counts and no reason, so Crossbeam's order is kept.
function rowsOf(j) {
  const sc = j.structuredContent || {};
  if (Array.isArray(sc.data)) return sc.data;
  if (sc.result && Array.isArray(sc.result.data)) return sc.result.data;
  let t = Array.isArray(j.content) && j.content[0] ? j.content[0].text : null;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
  return (t && Array.isArray(t.data)) ? t.data : (Array.isArray(t) ? t : []);
}
const seen = {};
const out = [];
for (const it of $input.all()) {
  for (const r of rowsOf(it.json || {})) {
    const domain = String((r && r.domain) || '').trim().toLowerCase();
    if (!domain || seen[domain]) continue;
    seen[domain] = true;
    out.push({ json: { domain: domain, partner_name: String(r.name || domain), invite_url: String(r.invite_url || '') } });
  }
}
return out;

