// Builds one Slack Block Kit brief (capped lengths, under 50 blocks) and the account picker form from Claude's JSON.
// Every section starts with a one-line explanation in italics so a first-time reader knows what it is and what to do.
const cfg = $('Configure me').first().json;
const d = $('Prepare brief input').first().json;
const ai = ($json.output && typeof $json.output === 'object') ? $json.output : {};
const NL = String.fromCharCode(10);
const DASHES = new RegExp('[' + String.fromCharCode(8212, 8211) + ']', 'g');
const cap = Math.min(10, Math.max(1, parseInt(cfg.max_items_per_run, 10) || 10));
const dry = cfg.dry_run === true || String(cfg.dry_run).toLowerCase() === 'true';
const crm = String(cfg.crm_choice || '').toLowerCase() === 'hubspot' ? 'HubSpot' : 'Salesforce';
const clip = (s, n) => { s = String(s == null ? '' : s).replace(DASHES, '-'); return s.length > n ? s.slice(0, n - 3) + '...' : s; };
const names = arr => arr.length <= 2 ? arr.join(', ') : arr.slice(0, 2).join(', ') + ' and ' + (arr.length - 2) + ' more';
const total = d.overlap_changes.length + d.net_new_accounts.length + d.partner_suggestions.length;
// The Claude node continues on error: it then returns { error } and no output.
const aiFailed = total > 0 && (!!$json.error || !$json.output);
// Which of your accounts the overlap list covers, from overlap_segments.
const segLabel = { prospects: 'prospects', open_opportunities: 'open opportunities', customers: 'customers', other: 'other accounts' };
const segs = String(cfg.overlap_segments || '').split(',').map(x => x.trim().toLowerCase()).filter(x => segLabel[x]).map(x => segLabel[x]);
const segText = segs.length ? 'your ' + segs.join(' and ') : 'your accounts';
// Salesforce links for overlap accounts (record_id is the CRM record id).
const sfBase = String(cfg.salesforce_base_url || '').replace(/\/+$/, '');
const sfOk = crm === 'Salesforce' && /^https:\/\//.test(sfBase) && sfBase.indexOf('YOUR_') === -1;
const link = (id, label) => (sfOk && /^[a-zA-Z0-9]{15,18}$/.test(String(id || ''))) ? '<' + sfBase + '/' + id + '|' + label.replace(/[<>|]/g, '') + '>' : label;
const header = t => ({ type: 'header', text: { type: 'plain_text', text: clip(t, 150) } });
const section = t => ({ type: 'section', text: { type: 'mrkdwn', text: clip(t, 2900) } });
const context = t => ({ type: 'context', elements: [{ type: 'mrkdwn', text: clip(t, 2900) }] });

// Join Claude's ICP fit and partner reasons back onto the lists by domain.
const fitOf = {};
for (const f of (Array.isArray(ai.net_new_fit) ? ai.net_new_fit : [])) if (f && f.domain) fitOf[String(f.domain).toLowerCase()] = f;
const whyOf = {};
for (const f of (Array.isArray(ai.partner_fit) ? ai.partner_fit : [])) if (f && f.domain) whyOf[String(f.domain).toLowerCase()] = f;
const rank = { high: 0, medium: 1, low: 2, unscored: 3 };
const netNew = d.net_new_accounts.map(a => {
  const f = fitOf[a.domain] || {};
  const fit = ['high', 'medium', 'low'].includes(String(f.fit).toLowerCase()) ? String(f.fit).toLowerCase() : 'unscored';
  return Object.assign({}, a, { icp_fit: fit, fit_reason: clip(f.reason || '', 200) });
}).sort((a, b) => (rank[a.icp_fit] - rank[b.icp_fit]) || (b.coverage_score - a.coverage_score));
// Hide accounts below min_icp_fit (high, medium or low). Unscored accounts are kept so nothing disappears silently.
const minFit = ['high', 'medium', 'low'].includes(String(cfg.min_icp_fit || '').toLowerCase()) ? String(cfg.min_icp_fit).toLowerCase() : 'low';
const passing = netNew.filter(a => a.icp_fit === 'unscored' || rank[a.icp_fit] <= rank[minFit]);
const netNewShown = passing.slice(0, cap);
const hiddenLowFit = netNew.length - passing.length;
// Partner suggestions Crossbeam returned before the re-nudge filter, to explain an empty section.
let rawSugg = 0;
try { rawSugg = $('Parse partner suggestions').all().filter(i => i.json.domain).length; } catch (e) { rawSugg = 0; }

const week = $now.toFormat('d LLL yyyy');
const blocks = [header('Weekly partner ecosystem brief')];
blocks.push(context('Week of ' + week + ' | ' + d.overlap_changes.length + ' changes on ' + segText + ' | ' + netNewShown.length + ' net-new accounts | ' + d.partner_suggestions.length + ' partners to invite' + (dry ? ' | dry run, nothing is written' : '')));
// A Crossbeam call that failed (for example an expired MCP credential) returns no structuredContent or content.
const failed = [['Fetch overlaps from Crossbeam', 'overlaps'], ['Fetch net-new accounts from Crossbeam', 'net-new accounts'], ['Fetch partner suggestions from Crossbeam', 'partner suggestions']]
  .filter(f => { try { return $(f[0]).all().some(i => !i.json.structuredContent && !i.json.content); } catch (e) { return false; } }).map(f => f[1]);
if (failed.length) blocks.push(context(':warning: Could not read ' + failed.join(', ') + ' from Crossbeam. Reconnect the Crossbeam MCP credential in n8n. This brief may be incomplete.'));
if (aiFailed) blocks.push(context(':warning: Claude could not finish the analysis this week, so priorities and fit scores are missing and the lists below are unranked. Check the Prioritise the week with Claude node in the n8n execution.'));
if (ai.summary) blocks.push(section(ai.summary));
const recOf = {};
for (const o of d.overlap_changes) { recOf[String(o.record_name || '').toLowerCase()] = o.record_id; if (o.website) recOf[String(o.website).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0]] = o.record_id; }
const pr = (Array.isArray(ai.priorities) ? ai.priorities : []).slice(0, 3);
if (pr.length) blocks.push(section('*Top priorities this week*' + NL + '_Who to contact this week: the account, the partner to work with, why, and the ask._' + NL + pr.map((p, i) => {
  const rid = p.record_id || recOf[String(p.domain || '').toLowerCase()] || recOf[String(p.name || '').toLowerCase()];
  return (i + 1) + '. *' + link(rid, clip(p.name || p.domain, 80)) + '*' + (p.partner ? ' with partner *' + clip(p.partner, 60) + '*' : '') + ': ' + clip(p.why, 220)
    + (p.partner_owner ? NL + '    Partner account owner: ' + clip(p.partner_owner, 100) : '')
    + (p.next_step ? NL + '    Next step: ' + clip(p.next_step, 180) : '');
}).join(NL)));
blocks.push({ type: 'divider' });

const ov = d.overlap_changes.slice().sort((x, y) => (y.has_partner_opp === true) - (x.has_partner_opp === true)).slice(0, cap);
if (ov.length) {
  const line = o => {
    const who = '*' + link(o.record_id, clip(o.record_name || o.website, 60)) + '*';
    const np = Array.isArray(o.new_partners) ? o.new_partners : [];
    const opp = o.has_partner_opp ? ' At least one partner has an open opportunity there.' : '';
    if (o.change === 'new_account') return '- ' + who + ': now in the data of ' + np.length + ' partner' + (np.length === 1 ? '' : 's') + ' (' + clip(names(np), 100) + ').' + opp;
    if (o.change === 'new_partner') return '- ' + who + ': ' + clip(names(np), 100) + (np.length === 1 ? ' now has' : ' now have') + ' it too (' + o.partner_count + ' partners in total).' + opp;
    return '- ' + who + ': a partner now has this account as an open opportunity.';
  };
  let t = '*Overlap changes on ' + segText + '*' + NL + '_Accounts in your CRM that showed up in partners\' data this week, or where a partner opened a deal. Those partners can help you close._' + NL + ov.map(line).join(NL);
  if (d.overlap_changes.length > cap) t += NL + '...and ' + (d.overlap_changes.length - cap) + ' more';
  blocks.push(section(t));
}
if (d.overlap_first_run) blocks.push(context(dry
  ? 'Dry run: history is not saved, so every test run lists overlaps from the last ' + (cfg.lookback_days || 7) + ' days. The first live run saves the baseline, then only real changes are listed.'
  : 'First run: existing overlaps were saved as a baseline. Only overlaps from the last ' + (cfg.lookback_days || 7) + ' days are listed.'));
if (netNewShown.length) blocks.push(section('*Net-new accounts your partners already sell to*' + NL + '_Companies not in your CRM that are customers of your partners, rated against your ICP. Tick the ones you want in the thread to create them in ' + crm + '._' + NL + netNewShown.map(a => '- *' + clip(a.account_name, 60) + '* (' + a.domain + '): customer of ' + a.partner_count + ' partner' + (a.partner_count === 1 ? '' : 's') + ' (' + clip(a.partner_list, 90) + '). ICP fit: ' + a.icp_fit + (a.fit_reason ? ', ' + a.fit_reason : '')).join(NL)));
if (hiddenLowFit > 0) blocks.push(context(netNewShown.length
  ? hiddenLowFit + ' lower-fit net-new account' + (hiddenLowFit === 1 ? ' was' : 's were') + ' hidden (min_icp_fit is ' + minFit + ').'
  : 'Net-new accounts: Claude rated ' + netNew.length + ' compan' + (netNew.length === 1 ? 'y' : 'ies') + ' that your partners sell to and none reached min_icp_fit (' + minFit + '), so there is nothing to approve this week. Sharpen icp_description, or set min_icp_fit to low in Configure me to review them anyway.'));
const sugg = d.partner_suggestions.slice(0, 10);
if (sugg.length) {
  blocks.push({ type: 'divider' });
  blocks.push(section('*Partners worth inviting*' + NL + '_Companies Crossbeam suggests you connect with. You are not partners yet, so there is no shared data. Invite opens the Crossbeam invite page._'));
  for (const s of sugg) {
    const why = (whyOf[s.domain] || {}).why_fit;
    const b = section('*' + clip(s.partner_name, 80) + '* (' + s.domain + ')' + (why ? NL + 'Why it could fit: ' + clip(why, 220) : ''));
    if (s.invite_url) b.accessory = { type: 'button', text: { type: 'plain_text', text: 'Invite' }, url: s.invite_url, action_id: 'invite_' + s.domain.replace(/[^a-z0-9]/g, '_').slice(0, 200) };
    blocks.push(b);
  }
} else if (rawSugg > 0) {
  blocks.push(context('Partners worth inviting: Crossbeam suggested ' + rawSugg + ' compan' + (rawSugg === 1 ? 'y' : 'ies') + ' that ' + (rawSugg === 1 ? 'was' : 'were') + ' already shown in the last ' + (cfg.renudge_after_weeks || 4) + ' weeks, so ' + (rawSugg === 1 ? 'it is' : 'they are') + ' hidden until then (renudge_after_weeks).'));
}
if (!failed.length && !ov.length && !netNewShown.length && !sugg.length) blocks.push(section('Quiet week: no overlap changes, net-new accounts or partner suggestions.'));
blocks.push(context('Priorities and fit scores are written by Claude from Crossbeam data and your ICP description, so check before acting.' + (d.list_link ? ' <' + d.list_link + '|Open the overlap list in Crossbeam>' : '')));

// Account picker for the human approval step.
const obj = String(cfg.salesforce_object || '').toLowerCase() === 'lead' ? 'Lead' : 'Account';
const offered = netNewShown.map(a => Object.assign({}, a, { label: clip(a.account_name, 60) + ' | ' + a.domain + ' | ' + a.icp_fit + ' fit' }));
const formJson = JSON.stringify([{ fieldLabel: 'Accounts to create', fieldType: 'checkbox', requiredField: false, fieldOptions: { values: offered.map(o => ({ option: o.label })) } }]);
const formMessage = '*' + offered.length + ' net-new account' + (offered.length === 1 ? ' is' : 's are') + ' ready to create in ' + crm + (crm === 'Salesforce' ? ' as ' + obj + 's' : '') + '.* Click the button, tick the ones you want and submit. Unticked accounts are not offered again.' + (dry ? ' Dry run is on: nothing will be written, you will get a would create list instead.' : '');
return [{ json: {
  text: 'Weekly partner ecosystem brief: ' + d.overlap_changes.length + ' overlap changes, ' + netNewShown.length + ' net-new accounts, ' + d.partner_suggestions.length + ' partners to invite',
  blocks: blocks.slice(0, 50),
  offered: offered,
  form_json: formJson,
  form_message: formMessage
} }];
